SELECT end_cohort, unique_statuss, basic_count FROM (SELECT CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, COUNT(DISTINCT monthly_fee) AS unique_statuss, SUM(CASE WHEN plan = 'basic' THEN 1 ELSE 0 END) AS basic_count FROM subscriptions GROUP BY CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS sub WHERE unique_statuss < 8 ORDER BY end_cohort LIMIT 10;
